const dataSourceSecret = crypto.createHash('sha256').update(process.env.DATA_SOURCE_SECRET || jwtSecret).digest();
const upload = multer({ storage: multer.memoryStorage(), limits: { fileSize: 10 * 1024 * 1024 } });
