const route = fn => (req,res,next) => Promise.resolve(fn(req,res,next)).catch(next);
const publicUser = row => ({ id:row.id, name:row.name, email:row.email, role:row.role, status:row.status, teamId:row.team_id, teamName:row.team_name });
const normalize = val => String(val ?? '').trim().normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,'');
const numeric = val => { const number=Number(String(val).replace('%','').replace(',','.')); return Number.isFinite(number) && number >= 0 ? number : null; };
const dateKey = value => value instanceof Date ? value.toISOString().slice(0,10) : String(value).slice(0,10);
const encryptSecret = value => { const iv=crypto.randomBytes(12);const cipher=crypto.createCipheriv('aes-256-gcm',dataSourceSecret,iv);const encrypted=Buffer.concat([cipher.update(value,'utf8'),cipher.final()]);return `v1.${iv.toString('hex')}.${cipher.getAuthTag().toString('hex')}.${encrypted.toString('hex')}`; };
function auth(req,res,next) { const token=req.headers.authorization?.replace('Bearer ',''); if(!token)return res.status(401).json({error:'Autenticação necessária.'}); try { req.user=jwt.verify(token,jwtSecret); next(); } catch { res.status(401).json({error:'Sessão inválida ou expirada.'}); } }
function allow(...allowed) { return (req,res,next) => allowed.includes(req.user.role) ? next() : res.status(403).json({error:'Você não tem permissão para esta ação.'}); }
const moduleRoutes = [
	['/teams',['TEAMS','ACTIONS']], ['/indicators',['INDICATORS','GOALS','ACTIONS']],
	['/goals',['GOALS','INDICATORS','PERFORMANCE']], ['/goal-change-requests',['AUTHORIZATIONS','GOALS']],
	['/actions',['ACTIONS']], ['/imports',['IMPORTS']], ['/reports',['REPORTS']], ['/conversations',['MESSAGES']]
];
async function configuredModuleAccess() { const row=(await query("SELECT value FROM settings WHERE key='module_access'")).rows[0];return row?.value||defaultModuleAccess; }
function metrics(target,achieved,direction='HIGHER_IS_BETTER') { target=Number(target); achieved=Number(achieved); const achievement=target ? (direction==='LOWER_IS_BETTER' ? (achieved<=target?100:target/Math.max(achieved,.01)*100) : achieved/target*100) : 0; return {target,achieved,difference:direction==='LOWER_IS_BETTER'?achieved-target:target-achieved,achievement:Math.max(0,achievement)}; }
async function period(id) { const data=await query(id?'SELECT * FROM periods WHERE id=$1':"SELECT * FROM periods WHERE status='OPEN' ORDER BY start_date DESC LIMIT 1",id?[id]:[]); return data.rows[0]; }
async function audit(req,action,entity,id,oldData,newData) { await query('INSERT INTO audit_logs(user_id,action,entity,entity_id,old_data,new_data,ip_address) VALUES($1,$2,$3,$4,$5,$6,$7)',[req.user?.id||null,action,entity,id||null,oldData?JSON.stringify(oldData):null,newData?JSON.stringify(newData):null,req.ip]); }
async function actionAccess(req, actionId) {
	if (roles[req.user.role] >= roles.MANAGER) return (await query('SELECT * FROM actions WHERE id=$1',[actionId])).rows[0];
	const condition=req.user.role==='SUPERVISOR'?'at.team_id=$2':'at.user_id=$2';
	return (await query(`SELECT DISTINCT a.* FROM actions a JOIN action_targets at ON at.action_id=a.id WHERE a.id=$1 AND ${condition}`,[actionId,req.user.role==='SUPERVISOR'?req.user.teamId:req.user.id])).rows[0];
}
function weightedAllocation(total, sellers) {
	const units=Math.max(0,Math.round(Number(total)));
	if(!sellers.length||!units)return sellers.map(seller=>({...seller,suggested:0}));
	const weighted=sellers.map(seller=>{const target=Number(seller.target||0);const achieved=Number(seller.achieved||0);const gap=Math.max(0,target-achieved);const capacity=Math.max(1,Number(seller.daily_capacity||0),achieved/Math.max(1,new Date().getDate()));const risk=target?Math.max(0,1-achieved/target):.5;return {...seller,weight:Math.max(.01,gap*.55+capacity*.3+risk*Math.max(target,1)*.15)};});
	const totalWeight=weighted.reduce((sum,seller)=>sum+seller.weight,0);
	const raw=weighted.map(seller=>({...seller,raw:units*seller.weight/totalWeight}));
	let remaining=units-raw.reduce((sum,seller)=>sum+Math.floor(seller.raw),0);
	const remainderOrder=[...raw].sort((a,b)=>(b.raw-Math.floor(b.raw))-(a.raw-Math.floor(a.raw)));
	const bonuses=new Map(remainderOrder.map((seller,index)=>[seller.id,index<remaining?1:0]));
	return raw.map(seller=>({...seller,suggested:Math.floor(seller.raw)+(bonuses.get(seller.id)||0)}));
}

app.use('/api',(req,res,next)=>{const match=moduleRoutes.find(([prefix])=>req.path===prefix||req.path.startsWith(`${prefix}/`));if(!match)return next();auth(req,res,route(async()=>{if(req.user.role==='SUPER_ADMIN')return next();const access=await configuredModuleAccess();return match[1].some(module=>(access[req.user.role]||[]).includes(module))?next():res.status(403).json({error:'Este módulo não está habilitado para sua função.'});}));});

