app.post('/api/auth/login',route(async(req,res)=>{const {email,password}=req.body;if(!email||!password)return res.status(400).json({error:'E-mail e senha são obrigatórios.'});const data=await query('SELECT u.*,t.name team_name FROM users u LEFT JOIN teams t ON t.id=u.team_id WHERE lower(u.email)=lower($1)',[email]);const user=data.rows[0];if(!user||!(await bcrypt.compare(password,user.password_hash)))return res.status(401).json({error:'E-mail ou senha inválidos.'});if(user.status!=='ACTIVE')return res.status(403).json({error:'Este acesso está bloqueado ou inativo.'});const safe=publicUser(user);const token=jwt.sign(safe,jwtSecret,{expiresIn:'8h'});await audit({user:safe,ip:req.ip},'LOGIN','USER',user.id);res.json({token,user:safe});}));
