app.post('/api/auth/change-password',auth,route(async(req,res)=>{const {currentPassword,newPassword}=req.body;if(!newPassword||newPassword.length<8)return res.status(400).json({error:'A nova senha deve ter pelo menos 8 caracteres.'});const old=(await query('SELECT password_hash FROM users WHERE id=$1',[req.user.id])).rows[0];if(!(await bcrypt.compare(currentPassword||'',old.password_hash)))return res.status(400).json({error:'Senha atual inválida.'});await query('UPDATE users SET password_hash=$1,updated_at=now() WHERE id=$2',[await bcrypt.hash(newPassword,12),req.user.id]);await audit(req,'CHANGE_PASSWORD','USER',req.user.id);res.status(204).end();}));

