app.post('/api/users',auth,allow('SUPER_ADMIN'),route(async(req,res)=>{const {name,email,password}=req.body;let {role,teamId}=req.body;if(!name?.trim()||!email?.trim()||!password||password.length<8||!['MANAGER','SUPERVISOR','SELLER'].includes(role))return res.status(400).json({error:'Nome, e-mail, senha de 8 caracteres e função válida são obrigatórios.'});if(role==='SELLER'&&!teamId)return res.status(400).json({error:'Todo vendedor deve estar vinculado a uma mesa.'});if(role==='MANAGER')teamId=null;if(teamId&&!(await query("SELECT 1 FROM teams WHERE id=$1 AND status='ACTIVE'",[teamId])).rowCount)return res.status(400).json({error:'Mesa inválida ou inativa.'});const row=(await query('INSERT INTO users(name,email,password_hash,role,team_id) VALUES($1,$2,$3,$4,$5) RETURNING *',[name.trim(),email.trim().toLowerCase(),await bcrypt.hash(password,12),role,teamId||null])).rows[0];const item=(await query('SELECT u.*,t.name team_name FROM users u LEFT JOIN teams t ON t.id=u.team_id WHERE u.id=$1',[row.id])).rows[0];await audit(req,'CREATE','USER',row.id,null,publicUser(item));res.status(201).json({item:publicUser(item)});}));
app.patch('/api/users/:id',auth,allow('SUPER_ADMIN'),route(async(req,res)=>{const old=(await query('SELECT * FROM users WHERE id=$1',[req.params.id])).rows[0];if(!old)return res.status(404).json({error:'Usuário não encontrado.'});let {name,status,role,teamId,password}=req.body;const nextRole=role||old.role;if(!['MANAGER','SUPERVISOR','SELLER'].includes(nextRole))return res.status(400).json({error:'Função inválida.'});const nextTeam=nextRole==='MANAGER'?null:(teamId===null?null:(teamId||old.team_id));if(nextRole==='SELLER'&&!nextTeam)return res.status(400).json({error:'Todo vendedor deve permanecer vinculado a uma mesa.'});if(nextTeam&&!(await query('SELECT 1 FROM teams WHERE id=$1',[nextTeam])).rowCount)return res.status(400).json({error:'Mesa inválida.'});const passwordHash=password?(password.length>=8?await bcrypt.hash(password,12):null):null;if(password&&!passwordHash)return res.status(400).json({error:'A nova senha deve ter pelo menos 8 caracteres.'});const row=(await query('UPDATE users SET name=COALESCE($1,name),status=COALESCE($2,status),role=$3,team_id=$4,password_hash=COALESCE($5,password_hash),updated_at=now() WHERE id=$6 RETURNING *',[name?.trim()||null,status||null,nextRole,nextTeam,passwordHash,req.params.id])).rows[0];const item=(await query('SELECT u.*,t.name team_name FROM users u LEFT JOIN teams t ON t.id=u.team_id WHERE u.id=$1',[row.id])).rows[0];await audit(req,'UPDATE','USER',row.id,publicUser(old),publicUser(item));res.json({item:publicUser(item)});}));
app.delete('/api/users/:id',auth,allow('SUPER_ADMIN'),route(async(req,res)=>{const old=(await query('SELECT * FROM users WHERE id=$1',[req.params.id])).rows[0];if(!old)return res.status(404).json({error:'Usuário não encontrado.'});if(String(old.id)===String(req.user.id))return res.status(400).json({error:'Você não pode excluir o próprio acesso.'});
	const client=await pool.connect();try{await client.query('BEGIN');await client.query('UPDATE audit_logs SET user_id=null WHERE user_id=$1',[old.id]);await client.query('UPDATE action_history SET user_id=null WHERE user_id=$1',[old.id]);await client.query('UPDATE goal_change_requests SET approved_by=null WHERE approved_by=$1',[old.id]);await client.query('UPDATE goals SET created_by=null WHERE created_by=$1',[old.id]);await client.query('UPDATE results SET created_by=null WHERE created_by=$1',[old.id]);await client.query('DELETE FROM imports WHERE uploaded_by=$1',[old.id]);await client.query('DELETE FROM action_comments WHERE user_id=$1',[old.id]);await client.query('DELETE FROM messages WHERE sender_id=$1',[old.id]);await client.query('DELETE FROM conversations WHERE created_by=$1',[old.id]);await client.query('DELETE FROM actions WHERE created_by=$1',[old.id]);await client.query('DELETE FROM goal_change_requests WHERE requested_by=$1',[old.id]);await client.query('DELETE FROM notifications WHERE user_id=$1',[old.id]);await client.query('DELETE FROM conversation_members WHERE user_id=$1',[old.id]);await client.query('DELETE FROM action_targets WHERE user_id=$1 OR supervisor_id=$1',[old.id]);await client.query('DELETE FROM results WHERE user_id=$1',[old.id]);await client.query('DELETE FROM goals WHERE user_id=$1',[old.id]);await client.query('DELETE FROM users WHERE id=$1',[old.id]);await client.query('INSERT INTO audit_logs(user_id,action,entity,entity_id,old_data,ip_address) VALUES($1,$2,$3,$4,$5,$6)',[req.user.id,'HARD_DELETE','USER',old.id,publicUser(old),req.ip]);await client.query('COMMIT');res.status(204).end();}catch(error){await client.query('ROLLBACK');throw error}finally{client.release()}
}));

app.get('/api/teams',auth,route(async(req,res)=>{const ownTeam=roles[req.user.role]<=roles.SUPERVISOR;const rows=(await query(`SELECT t.*,u.name supervisor_name,(SELECT count(*) FROM users s WHERE s.team_id=t.id AND s.role='SELLER' AND s.status='ACTIVE') seller_count FROM teams t LEFT JOIN users u ON u.id=t.supervisor_id ${ownTeam?'WHERE t.id=$1':''} ORDER BY t.name`,ownTeam?[req.user.teamId]:[])).rows;res.json({items:rows});}));
app.get('/api/teams/:id/performance',auth,route(async(req,res)=>{
	if(!/^[0-9a-f-]{36}$/i.test(req.params.id))return res.status(400).json({error:'Mesa inválida.'});
	if(roles[req.user.role]<=roles.SUPERVISOR&&String(req.user.teamId)!==String(req.params.id))return res.status(403).json({error:'Mesa fora do seu escopo.'});
	const team=(await query('SELECT t.*,u.name supervisor_name,u.email supervisor_email FROM teams t LEFT JOIN users u ON u.id=t.supervisor_id WHERE t.id=$1',[req.params.id])).rows[0];
	if(!team)return res.status(404).json({error:'Mesa não encontrada.'});
	const p=await period(req.query.periodId);
	if(!p)return res.json({team,period:null,summary:{},indicators:[],sellers:[],trend:[]});
	const performanceParams=[p.id,team.id];const sellerScope=req.user.role==='SELLER'?' AND u.id=$3':'';if(req.user.role==='SELLER')performanceParams.push(req.user.id);
	const result=(await query(`SELECT g.user_id,g.indicator_id,g.target_value,u.name user_name,i.name indicator_name,i.code,i.direction,i.type,i.unit,COALESCE(sum(r.result_value),0) achieved FROM goals g JOIN users u ON u.id=g.user_id JOIN indicators i ON i.id=g.indicator_id LEFT JOIN results r ON r.user_id=g.user_id AND r.indicator_id=g.indicator_id AND r.period_id=g.period_id WHERE g.period_id=$1 AND u.team_id=$2 AND u.role='SELLER' AND u.status='ACTIVE'${sellerScope} GROUP BY g.user_id,g.indicator_id,g.target_value,u.name,i.id ORDER BY u.name,i.name`,performanceParams)).rows;
	const configuredDays=Array.isArray(p.business_days)?p.business_days.map(dateKey).filter(Boolean):[];
	const start=new Date(`${dateKey(p.start_date)}T12:00:00`);const end=new Date(`${dateKey(p.end_date)}T12:00:00`);const today=new Date();today.setHours(12,0,0,0);
	const fallbackDays=[];for(let day=new Date(start);day<=end;day.setDate(day.getDate()+1))if(day.getDay()>0&&day.getDay()<6)fallbackDays.push(day.toISOString().slice(0,10));
	const businessDays=configuredDays.length?configuredDays:fallbackDays;const todayKey=today.toISOString().slice(0,10);
	const elapsedDays=Math.max(1,businessDays.filter(day=>day<=todayKey).length);const remainingDays=businessDays.filter(day=>day>todayKey).length;
	const rows=result.map(row=>{const values=metrics(row.target_value,row.achieved,row.direction);const dailyAverage=values.achieved/elapsedDays;const projected=values.achieved+dailyAverage*remainingDays;const gap=row.direction==='LOWER_IS_BETTER'?Math.max(0,values.achieved-values.target):Math.max(0,values.target-values.achieved);const dailyNeeded=row.direction==='LOWER_IS_BETTER'?0:(remainingDays?Math.max(0,values.target-values.achieved)/remainingDays:Math.max(0,values.target-values.achieved));return {...row,...values,gap,dailyAverage,dailyNeeded,projected,projectedAchievement:metrics(values.target,projected,row.direction).achievement};});
	const group=(items,key)=>items.reduce((map,item)=>{const value=item[key];if(!map.has(value))map.set(value,[]);map.get(value).push(item);return map;},new Map());
	const average=items=>items.length?items.reduce((sum,item)=>sum+Math.min(200,Number(item.achievement||0)),0)/items.length:0;
	const projectedAverage=items=>items.length?items.reduce((sum,item)=>sum+Math.min(200,Number(item.projectedAchievement||0)),0)/items.length:0;
	const indicators=[...group(rows,'indicator_id')].map(([id,items])=>{const target=items.reduce((sum,item)=>sum+item.target,0);const achieved=items.reduce((sum,item)=>sum+item.achieved,0);const projected=items.reduce((sum,item)=>sum+item.projected,0);return {id,name:items[0].indicator_name,code:items[0].code,direction:items[0].direction,type:items[0].type,unit:items[0].unit,target,achieved,gap:items.reduce((sum,item)=>sum+item.gap,0),dailyAverage:items.reduce((sum,item)=>sum+item.dailyAverage,0),dailyNeeded:items.reduce((sum,item)=>sum+item.dailyNeeded,0),projected,achievement:average(items),projectedAchievement:projectedAverage(items),sellerCount:items.length};}).sort((a,b)=>a.achievement-b.achievement);
	const sellers=[...group(rows,'user_id')].map(([id,items])=>({id,name:items[0].user_name,achievement:average(items),projectedAchievement:projectedAverage(items),criticalIndicators:items.filter(item=>item.achievement<60).length,indicators:items})).sort((a,b)=>b.achievement-a.achievement);
	const dailyRows=(await query(`SELECT r.user_id,r.indicator_id,r.reference_date,r.result_value,g.target_value,i.direction FROM results r JOIN goals g ON g.user_id=r.user_id AND g.indicator_id=r.indicator_id AND g.period_id=r.period_id JOIN users u ON u.id=r.user_id JOIN indicators i ON i.id=r.indicator_id WHERE r.period_id=$1 AND u.team_id=$2${sellerScope} ORDER BY r.reference_date`,performanceParams)).rows;
	const dates=[...new Set(dailyRows.map(row=>dateKey(row.reference_date)))];const cumulative=new Map();const trend=dates.map(date=>{for(const row of dailyRows.filter(item=>dateKey(item.reference_date)===date)){const key=`${row.user_id}:${row.indicator_id}`;cumulative.set(key,(cumulative.get(key)||0)+Number(row.result_value));}const values=rows.map(goal=>metrics(goal.target,cumulative.get(`${goal.user_id}:${goal.indicator_id}`)||0,goal.direction).achievement);return {date,achievement:values.length?values.reduce((sum,value)=>sum+Math.min(200,value),0)/values.length:0};});
	res.json({team,period:p,summary:{sellerCount:sellers.length,indicatorCount:indicators.length,achievement:average(rows),projectedAchievement:projectedAverage(rows),criticalCount:rows.filter(row=>row.achievement<60).length,elapsedDays,remainingDays},indicators,sellers,trend});
}));
app.post('/api/teams',auth,allow('SUPER_ADMIN','MANAGER'),route(async(req,res)=>{if(!req.body.name?.trim())return res.status(400).json({error:'Nome da mesa é obrigatório.'});const supervisor=req.body.supervisorId?(await query("SELECT id FROM users WHERE id=$1 AND role='SUPERVISOR' AND status='ACTIVE'",[req.body.supervisorId])).rows[0]:null;if(req.body.supervisorId&&!supervisor)return res.status(400).json({error:'Supervisor inválido ou inativo.'});const row=(await query('INSERT INTO teams(name,supervisor_id) VALUES($1,$2) RETURNING *',[req.body.name.trim(),supervisor?.id||null])).rows[0];if(supervisor)await query('UPDATE users SET team_id=$1,updated_at=now() WHERE id=$2',[row.id,supervisor.id]);await audit(req,'CREATE','TEAM',row.id,null,row);res.status(201).json({item:row});}));
app.patch('/api/teams/:id',auth,allow('SUPER_ADMIN','MANAGER'),route(async(req,res)=>{const old=(await query('SELECT * FROM teams WHERE id=$1',[req.params.id])).rows[0];if(!old)return res.status(404).json({error:'Mesa não encontrada.'});const hasSupervisor=Object.prototype.hasOwnProperty.call(req.body,'supervisorId');const supervisorId=hasSupervisor?(req.body.supervisorId||null):old.supervisor_id;if(supervisorId&&!(await query("SELECT 1 FROM users WHERE id=$1 AND role='SUPERVISOR' AND status='ACTIVE'",[supervisorId])).rowCount)return res.status(400).json({error:'Supervisor inválido ou inativo.'});const row=(await query('UPDATE teams SET name=COALESCE($1,name),supervisor_id=$2,status=COALESCE($3,status),updated_at=now() WHERE id=$4 RETURNING *',[req.body.name?.trim()||null,supervisorId,req.body.status||null,req.params.id])).rows[0];if(String(old.supervisor_id||'')!==String(supervisorId||'')){if(old.supervisor_id)await query('UPDATE users SET team_id=null,updated_at=now() WHERE id=$1 AND team_id=$2',[old.supervisor_id,row.id]);if(supervisorId)await query('UPDATE users SET team_id=$1,updated_at=now() WHERE id=$2',[row.id,supervisorId]);}await audit(req,'UPDATE','TEAM',row.id,old,row);res.json({item:row});}));
app.delete('/api/teams/:id',auth,allow('SUPER_ADMIN','MANAGER'),route(async(req,res)=>{const client=await pool.connect();try{await client.query('BEGIN');const old=(await client.query('SELECT * FROM teams WHERE id=$1 FOR UPDATE',[req.params.id])).rows[0];if(!old){await client.query('ROLLBACK');return res.status(404).json({error:'Mesa não encontrada.'});}const actionIds=(await client.query('SELECT DISTINCT action_id FROM action_targets WHERE team_id=$1',[old.id])).rows.map(row=>row.action_id);const affectedUsers=(await client.query("UPDATE users SET team_id=null,status='INACTIVE',updated_at=now() WHERE team_id=$1 RETURNING id",[old.id])).rowCount;await client.query('DELETE FROM conversations WHERE team_id=$1',[old.id]);await client.query('DELETE FROM teams WHERE id=$1',[old.id]);if(actionIds.length)await client.query('DELETE FROM actions WHERE id=ANY($1::uuid[]) AND NOT EXISTS (SELECT 1 FROM action_targets WHERE action_targets.action_id=actions.id)',[actionIds]);await client.query('INSERT INTO audit_logs(user_id,action,entity,entity_id,old_data,new_data,ip_address) VALUES($1,$2,$3,$4,$5,$6,$7)',[req.user.id,'HARD_DELETE','TEAM',old.id,JSON.stringify(old),JSON.stringify({affectedUsers}),req.ip]);await client.query('COMMIT');res.status(204).end();}catch(error){await client.query('ROLLBACK');throw error}finally{client.release()}}));

app.get('/api/periods',auth,route(async(_req,res)=>res.json({items:(await query('SELECT * FROM periods ORDER BY start_date DESC')).rows})));
app.post('/api/periods',auth,allow('SUPER_ADMIN','MANAGER'),route(async(req,res)=>{const {name,month,year,startDate,endDate,status}=req.body;if(!name?.trim()||!/^\d{4}-\d{2}-\d{2}$/.test(startDate||'')||!/^\d{4}-\d{2}-\d{2}$/.test(endDate||'')||startDate>endDate)return res.status(400).json({error:'Nome e intervalo de datas válido são obrigatórios.'});const row=(await query('INSERT INTO periods(name,month,year,start_date,end_date,status) VALUES($1,$2,$3,$4,$5,$6) RETURNING *',[name.trim(),month,year,startDate,endDate,status||'DRAFT'])).rows[0];await audit(req,'CREATE','PERIOD',row.id,null,row);res.status(201).json({item:row});}));
app.patch('/api/periods/:id',auth,allow('SUPER_ADMIN','MANAGER'),route(async(req,res)=>{const old=(await query('SELECT * FROM periods WHERE id=$1',[req.params.id])).rows[0];if(!old)return res.status(404).json({error:'Período não encontrado.'});const row=(await query('UPDATE periods SET name=COALESCE($1,name),month=COALESCE($2,month),year=COALESCE($3,year),start_date=COALESCE($4,start_date),end_date=COALESCE($5,end_date),status=COALESCE($6,status),business_days=COALESCE($7,business_days),updated_at=now() WHERE id=$8 RETURNING *',[req.body.name?.trim()||null,req.body.month||null,req.body.year||null,req.body.startDate||null,req.body.endDate||null,req.body.status||null,req.body.businessDays?JSON.stringify(req.body.businessDays):null,req.params.id])).rows[0];await audit(req,'UPDATE','PERIOD',row.id,old,row);res.json({item:row});}));
app.delete('/api/periods/:id',auth,allow('SUPER_ADMIN','MANAGER'),route(async(req,res)=>{const old=(await query('SELECT * FROM periods WHERE id=$1',[req.params.id])).rows[0];if(!old)return res.status(404).json({error:'Período não encontrado.'});const usage=(await query('SELECT (SELECT count(*) FROM goals WHERE period_id=$1)+(SELECT count(*) FROM results WHERE period_id=$1)+(SELECT count(*) FROM imports WHERE period_id=$1)+(SELECT count(*) FROM actions WHERE period_id=$1) count',[old.id])).rows[0];if(Number(usage.count)>0)return res.status(409).json({error:'O período possui metas, resultados, importações ou ações e não pode ser excluído.'});await query('DELETE FROM periods WHERE id=$1',[old.id]);await audit(req,'DELETE','PERIOD',old.id,old,null);res.status(204).end();}));
