app.get('/api/data-source',auth,allow('SUPER_ADMIN'),route(async(_req,res)=>{const row=(await query("SELECT value,updated_at FROM settings WHERE key='data_source_connection'")).rows[0];if(!row)return res.json({item:null});const {passwordEncrypted,...safe}=row.value;res.json({item:{...safe,hasPassword:Boolean(passwordEncrypted),updatedAt:row.updated_at}});}));
app.patch('/api/data-source',auth,allow('SUPER_ADMIN'),route(async(req,res)=>{const {type,address,database,username,password,enabled}=req.body;if(!['SERVER','CUBE'].includes(type)||!address?.trim()||!username?.trim())return res.status(400).json({error:'Tipo, endereço e login são obrigatórios.'});if(address.length>500||String(database||'').length>160||username.length>160)return res.status(400).json({error:'Os dados da conexão excedem o tamanho permitido.'});const current=(await query("SELECT value FROM settings WHERE key='data_source_connection'")).rows[0]?.value;if(!password&&!current?.passwordEncrypted)return res.status(400).json({error:'Informe a senha da fonte de dados.'});const value={type,address:address.trim(),database:String(database||'').trim(),username:username.trim(),passwordEncrypted:password?encryptSecret(password):current.passwordEncrypted,enabled:enabled!==false};await query("INSERT INTO settings(key,value,updated_at) VALUES('data_source_connection',$1,now()) ON CONFLICT(key) DO UPDATE SET value=EXCLUDED.value,updated_at=now()",[JSON.stringify(value)]);const safe={type:value.type,address:value.address,database:value.database,username:value.username,enabled:value.enabled,hasPassword:true};await audit(req,'UPDATE','DATA_SOURCE',null,null,safe);res.json({item:safe});}));
