app.post('/api/imports/:previewId/confirm',auth,allow('SUPER_ADMIN','MANAGER'),route(async(req,res)=>{const pending=pendingImports.get(req.params.previewId);if(!pending)return res.status(404).json({error:'Prévia expirada. Envie o arquivo novamente.'});const p=await period(req.body.periodId);if(!p)return res.status(400).json({error:'Selecione um período.'});const mapping={...pending.mapping,...(req.body.mapping||{})};const indicators=Object.fromEntries((await query('SELECT * FROM indicators WHERE active=true')).rows.map(item=>[item.code,item]));let success=0;const errors=[];for(const [index,data] of pending.rows.entries()){try{const sellerName=data[Object.keys(mapping).find(key=>mapping[key]==='seller')];if(!sellerName)throw new Error('Vendedor ausente');const seller=(await query("SELECT id FROM users WHERE lower(name)=lower($1) AND role='SELLER'",[sellerName])).rows[0];if(!seller)throw new Error(`Vendedor inexistente: ${sellerName}`);for(const [header,code] of Object.entries(mapping)){if(!indicators[code])continue;const result=numeric(data[header]);if(result===null)continue;await query("INSERT INTO results(user_id,indicator_id,period_id,result_value,reference_date,source,created_by) VALUES($1,$2,$3,$4,$5,'IMPORT',$6) ON CONFLICT(user_id,indicator_id,period_id,reference_date) DO UPDATE SET result_value=EXCLUDED.result_value,source='IMPORT',created_by=EXCLUDED.created_by",[seller.id,indicators[code].id,p.id,result,req.body.referenceDate||new Date().toISOString().slice(0,10),req.user.id]);}success++;}catch(error){errors.push({row:index+2,message:error.message});}}const row=(await query('INSERT INTO imports(file_name,uploaded_by,period_id,status,total_rows,success_rows,error_rows,errors,mapping) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9) RETURNING *',[pending.name,req.user.id,p.id,errors.length?'PROCESSED_WITH_ERRORS':'PROCESSED',pending.rows.length,success,errors.length,JSON.stringify(errors),JSON.stringify(mapping)])).rows[0];await audit(req,'IMPORT','IMPORT',row.id,null,row);pendingImports.delete(req.params.previewId);res.json({item:row,errors});}));
