app.patch('/api/conversations/:id',auth,route(async(req,res)=>{const old=(await query('SELECT * FROM conversations WHERE id=$1',[req.params.id])).rows[0];if(!old)return res.status(404).json({error:'Conversa não encontrada.'});if(String(old.created_by)!==String(req.user.id)&&roles[req.user.role]<roles.MANAGER)return res.status(403).json({error:'Somente o criador ou a gestão pode alterar esta conversa.'});const memberIds=Array.isArray(req.body.memberIds)?req.body.memberIds:null;const row=(await query('UPDATE conversations SET name=COALESCE($1,name),team_id=COALESCE($2,team_id) WHERE id=$3 RETURNING *',[req.body.name?.trim()||null,req.body.teamId||null,old.id])).rows[0];if(memberIds){await query('DELETE FROM conversation_members WHERE conversation_id=$1',[old.id]);for(const member of [...new Set([old.created_by,...memberIds])])await query('INSERT INTO conversation_members(conversation_id,user_id) VALUES($1,$2)',[old.id,member]);}await audit(req,'UPDATE','CONVERSATION',row.id,old,row);res.json({item:row});}));
app.delete('/api/conversations/:id',auth,route(async(req,res)=>{const old=(await query('SELECT * FROM conversations WHERE id=$1',[req.params.id])).rows[0];if(!old)return res.status(404).json({error:'Conversa não encontrada.'});if(String(old.created_by)!==String(req.user.id)&&roles[req.user.role]<roles.MANAGER)return res.status(403).json({error:'Somente o criador ou a gestão pode excluir esta conversa.'});await query('DELETE FROM conversations WHERE id=$1',[old.id]);await audit(req,'DELETE','CONVERSATION',old.id,old,null);res.status(204).end();}));
app.get('/api/conversations/:id/messages',auth,route(async(req,res)=>{const member=(await query('SELECT 1 FROM conversation_members WHERE conversation_id=$1 AND user_id=$2',[req.params.id,req.user.id])).rowCount;if(!member)return res.status(403).json({error:'Sem acesso a esta conversa.'});const items=(await query('SELECT m.*,u.name sender_name FROM messages m JOIN users u ON u.id=m.sender_id WHERE m.conversation_id=$1 ORDER BY m.created_at',[req.params.id])).rows;await query('UPDATE conversation_members SET last_read_at=now() WHERE conversation_id=$1 AND user_id=$2',[req.params.id,req.user.id]);res.json({items});}));
app.post('/api/conversations/:id/messages',auth,route(async(req,res)=>{if(!req.body.message?.trim())return res.status(400).json({error:'Mensagem vazia.'});const member=(await query('SELECT 1 FROM conversation_members WHERE conversation_id=$1 AND user_id=$2',[req.params.id,req.user.id])).rowCount;if(!member)return res.status(403).json({error:'Sem acesso a esta conversa.'});const row=(await query('INSERT INTO messages(sender_id,conversation_id,message) VALUES($1,$2,$3) RETURNING *',[req.user.id,req.params.id,req.body.message.trim()])).rows[0];res.status(201).json({item:row});}));
app.get('/api/notifications',auth,route(async(req,res)=>res.json({items:(await query('SELECT * FROM notifications WHERE user_id=$1 ORDER BY created_at DESC LIMIT 30',[req.user.id])).rows})));
app.patch('/api/notifications/:id/read',auth,route(async(req,res)=>{await query('UPDATE notifications SET read_at=now() WHERE id=$1 AND user_id=$2',[req.params.id,req.user.id]);res.status(204).end();}));
async function reportRows(req) { const p=await period(req.query.periodId);let scoped='',params=[p.id];if(req.user.role==='SUPERVISOR'){scoped=' AND u.team_id=$2';params.push(req.user.teamId);}if(req.user.role==='SELLER'){scoped=' AND u.id=$2';params.push(req.user.id);}const rows=(await query(`SELECT u.name vendedor,t.name mesa,i.name indicador,g.target_value meta,COALESCE(sum(r.result_value),0) realizado FROM goals g JOIN users u ON u.id=g.user_id LEFT JOIN teams t ON t.id=u.team_id JOIN indicators i ON i.id=g.indicator_id LEFT JOIN results r ON r.user_id=u.id AND r.indicator_id=i.id AND r.period_id=g.period_id WHERE g.period_id=$1 ${scoped} GROUP BY u.name,t.name,i.name,g.target_value ORDER BY u.name,i.name`,params)).rows;return {p,rows:rows.map(row=>({...row,diferenca:Number(row.meta)-Number(row.realizado),atingimento:Number(row.meta)?Number(row.realizado)/Number(row.meta)*100:0}))}; }
app.get('/api/reports/export.csv',auth,route(async(req,res)=>{const {p,rows}=await reportRows(req);res.attachment(`relatorio-${p.name}.csv`).type('text/csv').send(stringify(rows,{header:true}));}));
app.get('/api/reports/export.xlsx',auth,route(async(req,res)=>{const {p,rows}=await reportRows(req);const book=XLSX.utils.book_new();XLSX.utils.book_append_sheet(book,XLSX.utils.json_to_sheet(rows),'Relatório');const buffer=XLSX.write(book,{type:'buffer',bookType:'xlsx'});res.attachment(`relatorio-${p.name}.xlsx`).type('application/vnd.openxmlformats-officedocument.spreadsheetml.sheet').send(buffer);}));
app.get('/api/reports/export.pdf',auth,route(async(req,res)=>{const {p,rows}=await reportRows(req);res.setHeader('Content-Type','application/pdf');res.setHeader('Content-Disposition',`attachment; filename="relatorio-${p.name}.pdf"`);const doc=new PDFDocument({margin:40,size:'A4'});doc.pipe(res);doc.fontSize(18).fillColor('#172452').text('RV Digital — Relatório de Metas');doc.moveDown(.3).fontSize(10).fillColor('#64748b').text(`Período: ${p.name}`);doc.moveDown();doc.fillColor('#172452').fontSize(9).text('Vendedor',40,120).text('Mesa',175,120).text('Indicador',265,120).text('Meta',390,120).text('Realizado',455,120);let y=138;for(const row of rows.slice(0,42)){doc.fillColor('#243252').fontSize(8).text(row.vendedor,40,y,{width:125}).text(row.mesa||'-',175,y,{width:85}).text(row.indicador,265,y,{width:115}).text(Number(row.meta).toLocaleString('pt-BR'),390,y,{width:60,align:'right'}).text(Number(row.realizado).toLocaleString('pt-BR'),455,y,{width:70,align:'right'});y+=14;if(y>780){doc.addPage();y=50;}}doc.end();}));

app.use('/api',(_req,res)=>res.status(404).json({error:'Rota não encontrada.'}));
app.use((error,_req,res,_next)=>{console.error(error);if(error.code==='23505')return res.status(409).json({error:'Este registro já existe.'});res.status(error.status||500).json({error:error.message||'Erro interno do servidor.'});});
app.use((req,res)=>{const requested=decodeURIComponent(req.path==='/'?'/index.html':req.path);const candidate=path.resolve(root,`.${requested}`);const target=candidate.startsWith(root)&&fs.existsSync(candidate)&&fs.statSync(candidate).isFile()?candidate:path.join(root,'index.html');fs.readFile(target,(error,data)=>{if(error)return res.status(500).send('Execute npm run build antes de iniciar.');res.type(types[path.extname(target)]||'application/octet-stream').send(data);});});
app.listen(port,'0.0.0.0',()=>console.log(`RV Digital API disponível na porta ${port}`));
